//get url details from storage when the browser starts...
//else user will have to load it from the sheets

var urlData = {};

var isTabClosed = false;

//custom timer 6000 ms or 6 sec by default
var customTime = 6000;

//scraping window tab ID
var scrapingTabID = null;

//loading error
// chrome.storage.local.set({ scrapingStatus: false });
