//getting the loaded data, so that its not lost if chrome is closed after fetching the data
chrome.storage.local.get(["urlData"], function (lresult) {
  if (lresult.urlData == undefined) {
    return true;
  } else {
    urlData = lresult.urlData;
    console.log(urlData);
  }
});

//adding event listener for closing tabs
chrome.tabs.onRemoved.addListener(function (tabId, removeInfo) {
  if (tabId === scrapingTabID) {
    chrome.storage.local.set({ scrapingStatus: false });
    isTabClosed = true;
  }
});

//these actions are triggered by other scripts such as, popup.js, content.js
//to perform relevent actions
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.method == "googleSignIn") {
    googleSignIn();
  }

  if (request.method == "googleSignOut") {
    googleSignOut();
  }

  //redirect the user to google sheet;
  if (request.method == "goToGoogleSheet") {
    //check if a sheet is already created else create one and redirect
    //what if user has deleted the sheet? then create a new one
    chrome.storage.local.get(["sheetID", "sheetURL"], function (result) {

      if (result.sheetID == undefined) {
        createSheet();
      } else {
        //we got a sheet already so chill.
        //redirect to the sheet generated
        chrome.tabs.create({ url: result.sheetURL });
      }
    });
  }

  //getting urls and the xpath patterns which are used to scrape.
  if (request.method == "loadFromSheet") {
    loadFromSheet();
  }

  //this is triggered when user clicks start scraping button
  if (request.method == "start_scraping") {
    var urls = Object.keys(urlData);
    if (urls.length > 0) {
      var i = 1;

      chrome.storage.local.set({ scrapingStatus: true });
      //create new window and work on that...
      try {
        chrome.windows.create(
          {
            url: urls[0],
            type: "panel",
            focused: false,
          },
          function (win) {
            try {
              // win represents the Window object from windows API
              // Do something after opening

              //set tab ID locally, so that in content script, we perform action only on this tab ID
              scrapingTabID = win.tabs[0].id;

              var timer = setInterval(function myTimer() {
                console.log(i);
                if (i >= urls.length || isTabClosed) {
                  isTabClosed = false;
                  // chrome.tabs.remove(win.tabs[0].id);
                  scrapingTabID = null;
                  //update status
                  updateStatusInSheet();
                  //should remove storage too
                  const keys = ["urlData"];
                  chrome.storage.local.remove(keys, function () {
                    console.log("removed");
                  });

                  chrome.tabs //close the tab
                    .remove(win.tabs[0].id);

                  //setting scraping status to false
                  chrome.storage.local.set({ scrapingStatus: false });
                  urlData = {};

                  clearInterval(timer);
                  // return true;
                } else {
                  chrome.tabs.update(win.tabs[0].id, { url: urls[i] });
                  i++;
                }
              }, customTime);
            } catch (e) {
              console.log(e);
              //error, so remove the tab
              chrome.tabs //close the tab
                .remove(win.tabs[0].id);
              //setting scraping status to false
              chrome.storage.local.set({ scrapingStatus: false });
              urlData = {};
            }
          }
        );
      } catch (e) {
        clearInterval(timer);
        console.log(e);
        //setting scraping status to false
        chrome.storage.local.set({ scrapingStatus: false });
      }
    } else {
      // alert("no data to scrape, please check the sheet");
    }
  }

  //changing refresh time to scrap from pop up js
  if (request.method == "change_timer") {
    customTime = request.data;
  }

  //triggered by content script to know if we are in right tabID to perform the action,
  //and then content script gets the relevent xpaths to scrape and send back here.
  if (request.type == "url_visited") {
    //verify url and send response
    if (
      urlData[request.payload.message] != undefined &&
      sender.tab.id === scrapingTabID
    ) {
      sendResponse(urlData[request.payload.message]);
    } else {
      sendResponse("no");
    }
  }

  //here content script has scraped the data and sends it to push it to google sheet
  if (request.type == "scrapedData") {
    console.log(request.payload.data);
    appendData(request.payload.data, request.payload.message);
  }

  //same function as previous but for single xpath.
  if (request.type == "scrapedDataSingle") {
    appendData([request.payload.data], request.payload.message);
  }
  sendResponse();
  return true;
});

function googleSignIn() {
  chrome.identity.getAuthToken({ interactive: true }, function (token) {
    console.log("got the token", token);
    if (token != undefined) {
      chrome.storage.local.set({ userSignedIn: true });
      // alert("Signed in succesfully");
      console.log("signed in");
    }
  });
}

function googleSignOut() {
  chrome.storage.local.set({ userSignedIn: false });
  const keys = ["sheetID", "sheetURL", "urlData"];
  // chrome.identity.clearAllCachedAuthTokens();
  chrome.storage.local.remove(keys, function (items) {
    console.log("removed");
  });
  // alert("signed out");
}

