function loadFromSheet(_callback) {
  //get sheetID, and required local storage data before calling gapi
  chrome.storage.local.get(["sheetID", "sheetURL", "urls"], function (lresult) {
    //if we dont have sheetID, dont exicute further.
    if (lresult.sheetID == undefined) {
      // alert('click on "go to sheet" button to create a sheet first.');
      return;
    }

    console.log("request initiated");
    console.log(lresult.sheetID);
    chrome.identity.getAuthToken({ interactive: true }, function (token) {
      var myHeaders = new Headers();
      myHeaders.append("Authorization", "Bearer " + token);
      myHeaders.append("Content-Type", "application/json");

      var requestOptions = {
        method: "GET",
        headers: myHeaders,
        redirect: "follow",
      };

      fetch(
        "https://sheets.googleapis.com/v4/spreadsheets/" +
        lresult.sheetID +
        "/values/Sheet1?key=" +
        API_KEY,
        requestOptions
      )
        .then((response) => response.text())
        .then(function (result) {
          let res = JSON.parse(result);
          console.log(res);

          //after getting the sheet data......
          //remove existing local storage as we are loading new ones
          urlData = {};
          chrome.storage.local.remove(["urlData"], function (items) {
            console.log("removed");
          });

          //iterating through rows in the sheet
          for (var vi in res.values) {
            //we skip first and second row, as instructions are present...
            // console.log(res.values[vi]);
            if (vi == 0 || vi == 1 || res.values[vi][2] === "done") {
              continue;
            }
            //to print row
            // console.log(response.result.values[vi][0]);
            // console.log(response.result.values[vi][1]);

            //i.e vi[0] is first column in first row, and so onn...
            urlData[res.values[vi][0]] = res.values[vi][1];
          }
          //set the data in local storage, after reading them.
          var tempDict = {};
          tempDict["urlData"] = urlData;
          // console.log(urlData);

          if (res.values.length > 1) {
            chrome.storage.local.set(tempDict);

            // alert("sucessfully updated the data.");
            // return true;
          } else {
            // alert("the list is empty.");
            // return false;
          }
          //after getting the sheet data......
        })
        .catch(function (error) {
          console.log("error", error);
          // return false;
        });
      return true;
    });

    return true;
  });
}

function appendData(data, url) {
  var output = [];
  //arranging the data
  for (var vi in data) {
    output.push([url, data[vi]]);
  }

  chrome.storage.local.get(["sheetID"], function (lresult) {
    chrome.identity.getAuthToken({ interactive: true }, function (token) {
      //append data........
      var myHeaders = new Headers();
      myHeaders.append("Authorization", "Bearer " + token);
      myHeaders.append("Content-Type", "application/json");

      var raw = JSON.stringify({
        values: output,
      });

      var requestOptions = {
        method: "POST",
        headers: myHeaders,
        body: raw,
        redirect: "follow",
      };

      fetch(
        "https://sheets.googleapis.com/v4/spreadsheets/" +
        lresult.sheetID +
        "/values/Output:append?valueInputOption=USER_ENTERED&key=" +
        API_KEY,
        requestOptions
      )
        .then((response) => response.text())
        .then((result) => console.log(result))
        .catch((error) => console.log("error", error));

      //append data........
    });
  });
}

function updateStatusInSheet() {
  chrome.storage.local.get(["sheetID"], function (lresult) {
    if (lresult.sheetID != undefined) {
      console.log("request initiated");
      chrome.identity.getAuthToken({ interactive: true }, function (token) {
        var myHeaders = new Headers();

        myHeaders.append("Authorization", "Bearer " + token);

        myHeaders.append("Content-Type", "application/json");

        var requestOptions = {
          method: "GET",
          headers: myHeaders,
          redirect: "follow",
        };

        fetch(
          "https://sheets.googleapis.com/v4/spreadsheets/" +
          lresult.sheetID +
          "/values/Sheet1?key=" +
          API_KEY,
          requestOptions
        )
          .then((response) => response.text())
          .then(function (result) {
            let res = JSON.parse(result);
            //after getting sheet data
            console.log("input sheet, before status update");

            var statusList = [];
            for (var i = 0; i < res.values.length - 2; i++) {
              statusList.push(["done"]);
            }

            chrome.identity.getAuthToken(
              { interactive: true },
              function (tokenn) {
                var myHeaders = new Headers();
                myHeaders.append("Authorization", "Bearer " + tokenn);

                myHeaders.append("Content-Type", "application/json");

                var raw = JSON.stringify({
                  values: statusList,
                });

                var requestOptions = {
                  method: "PUT",
                  headers: myHeaders,
                  body: raw,
                  redirect: "follow",
                };

                fetch(
                  "https://sheets.googleapis.com/v4/spreadsheets/" +
                  lresult.sheetID +
                  "/values/Sheet1!C3?valueInputOption=USER_ENTERED&key=" +
                  API_KEY,
                  requestOptions
                )
                  .then((response) => response.text())
                  .then((result) => console.log(result))
                  .catch((error) => console.log("error", error));
              }
            );
          })
          .catch((error) => console.log("error", error));
      });
    }
  });
}
